# blog/signals.py
from django.db.models.signals import post_save
from django.dispatch import receiver


@receiver(post_save, sender=Post)
def post_saved(sender, instance, created, **kwargs):
    if created:
        print(f"New post: {instance.title}")

# blog/apps.py
class BlogConfig(AppConfig):
    name = "blog"

    def ready(self):
        from . import signals  # noqa: F401

class TimingMiddleware:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        # code before the view
        response = self.get_response(request)
        # code after the view
        response["X-Handled-By"] = "my-app"
        return response

class PostQuerySet(models.QuerySet):
    def published(self):
        return self.filter(published=True)


class Post(models.Model):
    # fields ...
    objects = PostQuerySet.as_manager()

# usage: Post.objects.published().order_by("-created_at")

class Meta:
    constraints = [
        models.UniqueConstraint(fields=["tenant", "slug"], name="uniq_slug_per_tenant"),
        models.CheckConstraint(condition=models.Q(price__gte=0), name="price_non_negative"),
    ]
    indexes = [models.Index(fields=["created_at"])]

from django.core.exceptions import ValidationError

class Event(models.Model):
    start = models.DateTimeField()
    end = models.DateTimeField()

    def clean(self):
        if self.end <= self.start:
            raise ValidationError("End must be after start.")

